import { parseAsString, parseAsStringEnum, useQueryStates } from "nuqs";

const todoStatusParser = parseAsStringEnum<
  TodoStatus
>(["all", "completed", "pending"]).withDefault("all");

const [filters, setFilters] = useQueryStates(
  {
    q: parseAsString.withDefault(""),
    status: todoStatusParser,
  },
  {
    history: "replace",
    // 搜索输入节流，避免每个按键都写 URL
    throttleMs: 300,
  },
);

const searchValue = filters.q;
const todoStatus = filters.status;
const setSearchValue = (q: string) => {
  void setFilters({ q: q || null }); // null 可清掉默认空 q
};
const setTodoStatus = (status: TodoStatus) => {
  void setFilters({ status: status === "all" ? null : status });
};

